mapper.select:
SELECT id, user_id, exp_value, reason, create_time
FROM user_exp_record
WHERE user_id = #{userId}
ORDER BY create_time DESC
LIMIT #{limit}

SELECT COUNT(*)
FROM user_exp_record
WHERE user_id = #{userId}
  AND reason = #{reason}
  AND DATE(create_time) = CURDATE()

SELECT COUNT(*)
FROM user_exp_record
WHERE user_id = #{userId}
  AND reason = #{reason}

mapper.delete:
DELETE FROM user_exp_record
WHERE user_id = #{userId}
  AND id NOT IN (
      SELECT id FROM (
          SELECT id FROM user_exp_record
          WHERE user_id = #{userId}
          ORDER BY create_time DESC
          LIMIT #{keepCount}
      ) AS tmp
  )
